function m2(n){return '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function n0(n){return n.toLocaleString('en-US');}
var NS=5;
var FOC='.hd>*,.bls,.bsub,.brec,.bcs,.bhi';
/* origins: name, green lot, cost in cents per kg, color */
var OR={BR:['Brazil Cerrado','GL-4510',520,'#A16207'],CO:['Colombia Huila','GL-4502',640,'#52525B'],ET:['Ethiopia Guji','GL-4471',760,'#A1A1AA'],
HN:['Honduras Marcala','GL-4533',580,'#0F766E'],DC:['Colombia decaf','GL-4519',790,'#D4D4D8']};
var BL=[{n:'Foundry espresso',k:'House blend',m:[['BR',50],['CO',30],['ET',20]]},{n:'Daybreak roast',k:'Breakfast blend',m:[['CO',60],['BR',40]]},
{n:'Mesa decaf',k:'Decaf',m:[['DC',100]]},{n:'Ridgeline cold brew',k:'Cold brew blend',m:[['BR',70],['CO',30]]}];
/* green grams per bag (allows for roast loss) and bag plus label cost in cents */
var BAG=[['12 oz',400,38],['5 lb',2650,95]];
var TEST=5000,S;
function mix(b,sw){return b.m.map(function(x){return [sw&&x[0]==='BR'?'HN':x[0],x[1]];});}
function pctSum(m){return m.reduce(function(s,x){return s+x[1];},0);}
function cpk(m){return m.reduce(function(s,x){return s+x[1]*OR[x[0]][2];},0)/100;}
function bagC(m,i){return Math.round(BAG[i][1]*cpk(m)/1000+BAG[i][2]);}
function usd(c){return '$'+(c/100).toFixed(2);}
function kgs(g){return (g/1000).toFixed(1);}
function uses(){return BL.filter(function(b){return b.m.some(function(x){return x[0]==='BR';});});}
function sw(){return S.sw;}
function render(){
var L=$('bls'),U=uses();
L.innerHTML='<div class="ct"><span>Blends</span><span class="ch c-idle">'+BL.length+' BOMs</span></div>'+BL.map(function(b,i){var hit=S.sw&&U.indexOf(b)>=0;return '<button type="button" class="row'+(S.open&&i===0?' sel':'')+(hit?' hit':'')+'" id="bl'+i+'"><span class="bnm"><b>'+b.n+'</b><small>'+mix(b,S.sw).map(function(x){return OR[x[0]][0].split(' ')[0]+' '+x[1]+'%';}).join(', ')+'</small></span><span class="ch '+(hit?'c-warn':'c-idle')+'">'+(hit?(S.saved?'v2':'Updated'):'v1')+'</span></button>';}).join('');
var B=BL[0],m=mix(B,S.sw),R=$('brec');
if(!S.open)R.innerHTML='<div class="ct"><span>Blend BOM</span></div><div class="empt"><b>No blend open</b><span>Pick a blend to see its origins, percentages and batch quantities.</span></div>';
else R.innerHTML='<div class="ct"><span>'+B.n+', '+B.k.toLowerCase()+'</span><span class="ch '+(S.saved?'c-ok':S.sw?'c-warn':'c-idle')+'">'+(S.saved?'v2 saved':S.sw?'v2 draft':'v1')+'</span></div>'
+'<div class="bfm"><label class="fld" id="bfl"><small>Resize to, kg</small><input id="bsz" value="'+(S.typed)+'" inputmode="numeric" autocomplete="off" aria-label="Batch size in kilograms"><span class="em" id="bem">Enter 1 to 200 kg</span></label><button type="button" class="bt'+(S.g===TEST?' pri':'')+'" id="brz">Resize</button><span class="note" id="bnt">'+'Now: '+(S.g===TEST?'test roast':'production batch')+', '+kgs(S.g)+' kg</span></div>'
+'<div class="mix">'+m.map(function(x){return '<i style="width:'+x[1]+'%;background:'+OR[x[0]][3]+'"></i>';}).join('')+'</div>'
+'<div class="bom"><div class="row h"><span>Origin</span><span>Green lot</span><span>Share</span><span>Batch kg</span></div>'+m.map(function(x,i){return '<div class="row'+(S.sw&&x[0]==='HN'?' sw':'')+'"><span class="bo"><i style="background:'+OR[x[0]][3]+'"></i>'+OR[x[0]][0]+'</span><span>'+OR[x[0]][1]+'</span><span id="bp'+i+'">'+x[1]+'%</span><span id="bk'+i+'">'+kgs(S.g*x[1]/100)+'</span></div>';}).join('')
+'<div class="row tot"><span>Total</span><span></span><span id="bpt">'+pctSum(m)+'%</span><span id="bkt">'+kgs(m.reduce(function(s,x){return s+S.g*x[1]/100;},0))+'</span></div></div>';
var W=$('bsub');
if(!S.rs)W.innerHTML='<div class="ct"><span>Substitution</span></div><div class="empt"><b>No swaps pending</b><span>When a green lot runs out, swap it in every blend at once.</span></div>';
else if(!S.sw)W.innerHTML='<div class="ct"><span>Substitution</span><span class="ch c-bad">Running out</span></div><div class="sal"><b>GL-4510</b> Brazil Cerrado has 1 bag left. '+U.length+' blends use it.</div><div class="sal ok" style="margin-top:6px">Suggested: <b>GL-4533</b> Honduras Marcala, 32 bags on hand.</div><div class="sbt"><button type="button" class="bt pri" id="bsw">Swap Brazil for Honduras</button></div>';
else W.innerHTML='<div class="ct"><span>Substitution</span><span class="ch c-ok">Applied</span></div><div class="sal ok">Honduras Marcala replaces Brazil Cerrado in <b id="bsn">'+U.length+'</b> blends and <b id="bsb">'+U.length*BAG.length+'</b> bag sizes.</div><div class="row hd2"><span>Blend</span><span>Honduras share</span></div>'+U.map(function(b,i){var x=b.m.filter(function(y){return y[0]==='BR';})[0];return '<div class="row"><span>'+b.n+'</span><span class="mono" id="bu'+i+'">'+x[1]+'%</span></div>';}).join('');
var C=$('bcs'),old=mix(B,false),nw=mix(B,true);
if(!S.sw)C.innerHTML='<div class="ct"><span>Cost per bag</span></div><div class="empt"><b>No change to cost</b><span>Swap an origin to see cost per bag before you save.</span></div>';
else if(!S.cost)C.innerHTML='<div class="ct"><span>Cost per bag</span><button type="button" class="bt pri" id="bcp">Show cost per bag</button></div><div class="empt"><b>Draft not costed</b><span>Green cost at '+usd(cpk(old))+' per kg before the swap.</span></div>';
else C.innerHTML='<div class="ct"><span>Cost per bag, '+B.n+'</span><span class="mut" style="font-weight:400;font-size:9px" id="bck">Green '+usd(cpk(old))+' to '+usd(cpk(nw))+' per kg</span></div><div class="cg">'+BAG.map(function(g,i){var a=bagC(old,i),z=bagC(nw,i);return '<div class="cb"><small>'+g[0]+' bag</small><span class="vv"><s id="bco'+i+'">'+usd(a)+'</s><b id="bcn'+i+'">'+usd(z)+'</b></span><span class="dl" id="bcd'+i+'">+'+usd(z-a)+' per bag</span></div>';}).join('')+'</div>';
var H=$('bhi');
if(!S.open)H.innerHTML='<div class="ct"><span>Versions</span></div><div class="empt"><b>No history yet</b><span>Every saved version of the BOM is kept here.</span></div>';
else H.innerHTML='<div class="ct"><span>Versions</span>'+(S.saved?'<span class="ch c-ok">2 versions</span>':'')+'</div><div class="row h"><span>Ver</span><span>Change</span><span>Date</span><span>Status</span></div>'
+(S.saved?'<div class="row cur"><span class="mono">v2</span><span>Honduras Marcala for Brazil Cerrado</span><span>Nov 18</span><span class="ch c-ok" id="bv2">Current</span></div>':'')
+'<div class="row"><span class="mono">v1</span><span>Brazil 50, Colombia 30, Ethiopia 20</span><span>Nov 2</span><span class="ch '+(S.saved?'c-idle':'c-ok')+'" id="bv1">'+(S.saved?'Kept for reference':'Current')+'</span></div>'
+(S.cost&&!S.saved?'<div class="hbt"><button type="button" class="bt pri" id="bsv">Save as v2</button><span class="mut" style="font-size:8.8px">v1 stays for reference</span></div>':'');
var st=$('bst');st.textContent=S.saved?'v2 saved':S.sw?'Swap drafted':S.open?'Blend open':'No blend open';st.className='ch '+(S.saved?'c-ok':S.sw?'c-warn':S.open?'c-info':'c-idle');}
function szVal(){var e=$('bsz');if(!e)return NaN;var v=String(e.value).trim();return /^\d{1,3}$/.test(v)&&+v>=1&&+v<=200?(+v)*1000:NaN;}
winEl.addEventListener('input',function(e){if(e.target&&e.target.id==='bsz')S.typed=e.target.value;});
function typeIn(id,t,done){var i=0;(function k(){var e=$(id);if(e)e.value=t.slice(0,i);if(i<t.length){i++;later(k,90);}else done();})();}
function resetState(){S={open:false,g:TEST,typed:'120',rs:false,sw:false,cost:false,saved:false};render();}
var CAPAT=function(hh){return cur<=1||cur>=4?{l:14,t:visH()-hh-14}:{l:236,t:visH()-hh-14};};
var ST=[
{id:'open',target:function(){return $('bl0');},prompt:'Open the Foundry espresso house blend',where:'right',run:function(){S.open=true;render();},
 after:function(){var m=BL[0].m;return['A blend is a BOM by origin',BL[0].n+': '+m.map(function(x){return OR[x[0]][0].split(' ')[0]+' '+x[1]+'%';}).join(', ')+', '+pctSum(m)+'% in total.'];}},
{id:'size',target:function(){return $('brz');},prompt:'Resize to a 120 kg production batch',where:'below',
 ok:function(){var b=isNaN(szVal())||szVal()===TEST;var f=$('bfl');if(f)f.classList.toggle('err',b);return !b;},
 run:function(quick){var go=function(g){S.g=g;S.typed=String(g/1000);S.rs=true;render();};if(mode==='watch'&&!quick){var e=$('bsz');if(e)e.value='';typeIn('bsz','120',function(){go(120000);});S.g=120000;S.rs=true;}else go(quick?120000:szVal());},
 after:function(){var m=BL[0].m;return['From test roast to production',kgs(TEST)+' kg test roast to a '+kgs(S.g)+' kg batch: '+m.map(function(x){return kgs(S.g*x[1]/100)+' kg '+OR[x[0]][0].split(' ')[0];}).join(', ')+'.'];}},
{id:'swap',target:function(){return $('bsw');},prompt:'Swap Brazil for Honduras in every blend',where:'above',run:function(){S.sw=true;S.rs=true;render();},
 after:function(){var U=uses();return['One swap, every blend','Honduras Marcala replaces Brazil Cerrado in '+U.length+' blends and '+U.length*BAG.length+' bag sizes. Each blend still adds up to 100%.'];}},
{id:'cost',target:function(){return $('bcp');},prompt:'Show the cost per bag',where:'below',run:function(){S.cost=true;render();},
 after:function(){var o=mix(BL[0],false),n=mix(BL[0],true);return['Cost per bag before you save',BL[0].n+' '+BAG[0][0]+' goes from '+usd(bagC(o,0))+' to '+usd(bagC(n,0))+', '+BAG[1][0]+' from '+usd(bagC(o,1))+' to '+usd(bagC(n,1))+'.'];}},
{id:'save',target:function(){return $('bsv');},prompt:'Save the BOM as v2',where:'above',run:function(){S.saved=true;render();},
 after:function(){return['The earlier version stays','v2 with Honduras Marcala is current. v1 with Brazil Cerrado is kept for reference.'];}}];

/* ===== Watch and Try it engine (shared by the four Electronics cards). Tune the feel here. ===== */
var TUNE={startDelay:750,lead:900,press:300,dwell:2900,hold:2500,nextPrompt:1400,watch:'Watching',turn:'Your turn',done:'Done'};
var mode='watch',cur=0,watchOn=false;
var bar=document.createElement('div');bar.className='tbar';
var tgl=document.createElement('div');tgl.className='mtg';tgl.setAttribute('role','group');tgl.setAttribute('aria-label','Demo mode');
tgl.innerHTML='<button type="button" data-m="watch" aria-pressed="true">Watch</button><button type="button" data-m="try" aria-pressed="false">Try it</button>';
var md=document.createElement('div');md.className='mode';md.setAttribute('aria-hidden','true');
bar.appendChild(tgl);bar.appendChild(md);bar.appendChild(rp);shot.appendChild(bar);
var live=document.createElement('div');live.className='sr';live.setAttribute('aria-live','polite');winEl.appendChild(live);
var hs=$('hs'),pv=$('pv'),nx=$('nx'),sn=$('sn');
function setPill(){var n=mode==='done'?NS:Math.min(cur+1,NS),k=mode==='watch'?'':mode==='try'?'t':'d',t=mode==='watch'?TUNE.watch:mode==='try'?TUNE.turn:TUNE.done;
md.className='mode '+k;md.innerHTML='<span class="dt"></span><span>'+t+'</span><span class="mc">'+n+' of '+NS+'</span>';
[].forEach.call(tgl.children,function(b){b.setAttribute('aria-pressed',(b.getAttribute('data-m')==='watch')===(mode==='watch')?'true':'false');});
sn.textContent=n+' of '+NS;pv.disabled=mode!=='done'&&cur<=0;nx.disabled=mode==='done'||cur>=NS-1;}
function placeBox(box,l,t){var w=box.offsetWidth,hh=box.offsetHeight;box.style.left=Math.max(8,Math.min(visW()-w-8,l))+'px';box.style.top=Math.max(48,Math.min(visH()-hh-8,t))+'px';}
function capPos(){var hh=cap.offsetHeight;return typeof CAPAT==='function'?CAPAT(hh):{l:14,t:visH()-hh-14};}
function caption(i){var s=ST[i],a=typeof s.after==='function'?s.after():s.after;say2(i+1,a[0],a[1]);}
function say2(num,main,sub){clearTimeout(capT);live.textContent=main+(sub?'. '+sub:'');var run=function(){cap.innerHTML='<div class="m"><i>'+num+'</i>'+main+'</div>'+(sub?'<div class="s">'+sub+'</div>':'');cap.className='cap';cap.style.left='-999px';void cap.offsetWidth;var p=capPos();placeBox(cap,p.l,p.t);void cap.offsetWidth;cap.classList.add('on');};if(cap.classList.contains('on')){cap.classList.remove('on');capT=setTimeout(run,180);}else run();}
function hush(){clearTimeout(capT);cap.classList.remove('on');}
function prompt2(text,el,where){live.textContent=text;turn.innerHTML='<div class="m"><span class="pd"></span>'+text+'</div>';turn.className='cap turn';turn.style.left='-999px';void turn.offsetWidth;
var r=rel(el),hh=turn.offsetHeight,w=turn.offsetWidth,l=where==='right'?r.l+r.w+10:(where==='end'?r.l+r.w-w:r.l),t=where==='above'?r.t-hh-8:(where==='right'?r.t+r.h/2-hh/2:r.t+r.h+8);
if(where!=='above'&&where!=='right'&&t+hh>visH()-8)t=r.t-hh-8;placeBox(turn,l,t);void turn.offsetWidth;turn.classList.add('on');}
function turnOff(){turn.classList.remove('on');}
function hot(el,flash){if(!el){hs.className='hs';return;}var r=rel(el);hs.style.left=(r.l-3)+'px';hs.style.top=(r.t-3)+'px';hs.style.width=(r.w+6)+'px';hs.style.height=(r.h+6)+'px';hs.className='hs';void hs.offsetWidth;hs.className='hs '+(flash?'flash':'on');}
function clearHints(){[].slice.call(root.querySelectorAll('.hint,.fakehover,.press')).forEach(function(b){b.classList.remove('hint','fakehover','press');});}
function focusOff(){[].slice.call(root.querySelectorAll('.fade')).forEach(function(x){x.classList.remove('fade');});}
function focusOn(el){focusOff();if(!el)return;[].slice.call(winEl.querySelectorAll(FOC)).forEach(function(x){if(x===el||x.contains(el)||el.contains(x))return;x.classList.add('fade');});}
function cancelAll(){timers.forEach(clearTimeout);timers=[];watchOn=false;ghost.classList.remove('on','pr');hush();turnOff();clearHints();focusOff();hot(null);}
function gpos(el){var r=rel(el);return{l:r.l+Math.min(r.w*0.5,60),t:r.t+r.h*0.55};}
function watchStep(i,delay){cur=i;
later(function(){setPill();var el=ST[i].target();if(el)moveGhost(gpos(el));},delay);
later(function(){var el=ST[i].target();ghost.classList.add('pr');if(el){el.classList.add('fakehover','press');hot(el,true);}},delay+TUNE.lead);
later(function(){var el=ST[i].target();ghost.classList.remove('pr');if(el)el.classList.remove('fakehover','press');ST[i].run(false);caption(i);},delay+TUNE.lead+TUNE.press);
var end=delay+TUNE.lead+TUNE.press+TUNE.dwell;
if(i+1<NS)later(function(){watchStep(i+1,0);},end);
else later(function(){hush();ghost.classList.remove('on');later(function(){if(mode==='watch'&&visible)startWatch();},400);},end+TUNE.hold-400);}
function startWatch(){mode='watch';engaged=false;cancelAll();resetState();cur=0;setPill();if(reduce||!visible)return;watchOn=true;ghost.classList.add('on');moveGhost({l:visW()*0.5,t:visH()*0.5},true);watchStep(0,150);}
function showPrompt(){if(mode!=='try')return;var s=ST[cur];clearHints();hot(null);var el=s.target(),txt=s.prompt,b=s.back&&s.back();if(b){el=b[0];txt=b[1];}
if(!el){turnOff();return;}focusOn(el);el.classList.add('hint');hot(el,false);setPill();prompt2(TUNE.turn+'. '+txt,el,b?(b[2]||'below'):(s.where||'below'));}
function startTry(){mode='try';engaged=true;cancelAll();resetState();cur=0;setPill();showPrompt();}
function doStep(){var s=ST[cur];if(s.ok&&!s.ok()){showPrompt();return;}clearHints();turnOff();focusOff();hot(null);s.run(false);caption(cur);
if(cur+1<NS){cur++;setPill();later(showPrompt,TUNE.nextPrompt);}else{mode='done';setPill();}}
function jump(i){if(i<0||i>=NS)return;var m=mode==='watch'?'watch':'try';cancelAll();resetState();for(var k=0;k<i;k++)ST[k].run(true);cur=i;
if(m==='watch'&&!reduce){mode='watch';watchOn=true;ghost.classList.add('on');setPill();watchStep(i,150);}else{mode='try';engaged=true;setPill();showPrompt();}}
pv.addEventListener('click',function(e){e.stopPropagation();jump(mode==='done'?NS-1:cur-1);});
nx.addEventListener('click',function(e){e.stopPropagation();jump(cur+1);});
tgl.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('button');if(!b)return;if(b.getAttribute('data-m')==='watch'){visible=true;startWatch();}else startTry();});
rp.addEventListener('click',function(){if(mode==='watch'){visible=true;startWatch();}else startTry();});
winEl.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('.stp'))return;
if(mode==='watch'){e.preventDefault();e.stopPropagation();startTry();return;}
if(mode==='try'){var s=ST[cur],el=s.target(),b=s.back&&s.back();
if(!b&&el&&(el===e.target||el.contains(e.target))){e.preventDefault();e.stopPropagation();doStep();return;}
if(e.target.closest&&e.target.closest('input'))return;
setTimeout(showPrompt,40);}},true);
winEl.addEventListener('keydown',function(e){if(e.key==='Enter'&&e.target.tagName==='INPUT'&&mode==='try'){e.preventDefault();var s=ST[cur],el=s.target();if(el&&el.closest('.frm')&&el.closest('.frm').contains(e.target))doStep();}e.stopPropagation();});
root.addEventListener('scroll',function(e){var t=e.target;if(t&&t.nodeType===1&&(t.scrollTop||t.scrollLeft)&&!t.closest('.pop')){t.scrollTop=0;t.scrollLeft=0;}},true);
function onResize(){if(mode==='try')later(showPrompt,60);}
if('ResizeObserver'in window)new ResizeObserver(function(){onResize();}).observe(host.parentNode);
function startObserver(){if('IntersectionObserver'in window){new IntersectionObserver(function(es){es.forEach(function(en){visible=en.intersectionRatio>=0.3;
if(visible&&mode==='watch'&&!watchOn&&!reduce){watchOn=true;later(startWatch,TUNE.startDelay);}
if(!visible&&mode==='watch'&&watchOn){cancelAll();resetState();cur=0;setPill();}});},{threshold:[0,0.3,0.6]}).observe(host.parentNode);}else{visible=true;later(startWatch,TUNE.startDelay);}}

/* ===== Automotive control row (November 11, 2026 rules). Replaces fit() and placeStp() above. ===== */
var stpEl=host.querySelector('.stp'),snEl=$('sn');
pv.classList.add('ctl');nx.classList.add('ctl');
function fit(){var P=host.parentNode,W=P.clientWidth,c2=W<600,s=W/742,cv=root.host&&root.host.parentElement;
shot.style.setProperty('--cw',W+'px');shot.classList.toggle('nar',W<430);shot.classList.toggle('c2',c2);
if(cv&&cv.style)cv.style.aspectRatio=c2?(W/Math.round(102+600*s)).toFixed(4):'';
host.style.transform='scale('+s+')';ctlPlace(c2);if(!c2)placeStp();}
function placeStp(){var st=host.querySelector('.stp'),P=host.parentNode,sc=P.clientWidth/742;if(!st||!sc)return;var vh=(P.clientHeight-host.offsetTop)/sc;st.style.bottom=Math.max(44,Math.round(640-vh+28))+'px';}
function ctlPlace(c2){if(typeof bar==='undefined'||!bar||!stpEl)return;
if(c2&&pv.parentNode!==bar){bar.insertBefore(pv,md);bar.insertBefore(nx,rp);}
else if(!c2&&pv.parentNode!==stpEl){stpEl.insertBefore(pv,snEl);stpEl.appendChild(nx);}
pv.classList.toggle('ctl',c2);nx.classList.toggle('ctl',c2);}
